    exMegalodon: 'मेगालोडन:',
    exSaves: 'बचत:',
    walletCaption: 'गुगल, एप्पल, टेलिग्राम, ईमेल, एसएमएस वा पासकीमा साइन अप गर्नुहोस् र केही क्लिकहरूमा तपाईंको लागि वालेट उत्पन्न हुन्छ । कुनै निजी कुञ्जी व्यवस्थापन वा हिरासत छैन: तपाईं आफ्नो सम्पत्तिको पूर्ण नियन्त्रणमा हुनुहुन्छ र हामी तपाईंको कोषमा कहिले पनि पहुँच गर्दैनौं ।',
    accountsDesc: 'DeHub मा धेरै तरिकाहरू छन् र ती मध्ये कुनै पनि तपाईंलाई पहिले नै वालेटको स्वामित्व लिन आवश्यक छैन । गुगल, एप्पल वा टेलिग्राममा साइन इन गर्नुहोस्, तपाईंको इमेल ठेगानामा वा एसएमएस मार्फत पठाइएको कोडको साथ, तपाईंको फोन वा कम्प्युटरमा पासकीको साथ, वा तपाईंले पहिले नै प्रयोग गर्नुभएको वालेट जडान गरेर । वालेट मार्ग बाहेक सबै कुराले पृष्ठभूमिमा तपाईंको लागि गैर - कस्टोडियल वालेट उत्पन्न गर्दछ: तपाईं कुञ्जीहरू राख्नुहुन्छ, हामी कहिले पनि हिरासतमा लिदैनौं, र ग्यास प्रायोजित हुन्छ ताकि तपाईं कहिल्यै नेटिभ टोकन खरीद नगरी पोष्ट, टिप र स collect्कलन गर्न सक्नुहुनेछ । तपाईंलाई त्यो वालेटलाई पहिलो पटक प्रयोग गर्दा मात्र सुरक्षित गर्न भनिएको छ, साइन अप गर्दा होइन ।',
    accountsB1Desc: 'गुगल, एप्पल वा टेलिग्राम, एक ट्याप, तपाईंको लागि सिर्जना गरिएको वालेट र पहिलो पोष्टबाट प्रायोजित ग्यास ।',
    accountsB3Desc: 'MetaMask, Rainbow, Trust, Phantom वा WalletConnect ले बोल्ने कुनै पनि कुरा जडान गर्नुहोस्, र ठेगाना प्रमाणित गर्न एक पटक हस्ताक्षर गर्नुहोस् । यदि प्रेत साइन - इन अस्वीकार गरिएको छ किनभने यसको Ethereum ठेगानाको कुनै इतिहास छैन भने, तपाईं यसको सट्टामा आफ्नो सोलाना वालेट प्रमाणित गर्न सक्नुहुन्छ । वालेट प्रयोगकर्ताहरूले आफ्नै ग्यास तिर्छन् ।',
    accountsB5Desc: 'नयाँ सदस्य निर्देशिकामा जग्गा जोड्ने र उनीहरूको पहिलो तीस दिनको लागि उनीहरूको नामको छेउमा नयाँ - सदस्य चिप बोक्ने सबैजना, ताकि समुदायले उनीहरूलाई भेट्न र स्वागत गर्न सकून् । नयाँ सदस्यहरूलाई वैकल्पिक निर्देशित पदयात्रा पनि प्रदान गरिन्छ, जसलाई पछि सेटिङहरूबाट पुनः खोल्न सकिन्छ ।',
    accountsB6: 'पासकी:',
    accountsB6Desc: '"फिंगरप्रिन्टको साथ जारी राख्नुहोस्" छनौट गर्नुहोस् र पासकी नै खाता हो — कुनै ईमेल, कुनै फोन नम्बर, कुनै पासवर्ड छैन । उही पासकीले वेबसाइट र एन्ड्रोइड अनुप्रयोगमा काम गर्दछ ।',
    accountsB7: 'आयात वा माइग्रेट गर्नुहोस्:',
    accountsB7Desc: 'साइन - इन पानामा तपाईंले पहिले नै समात्नुभएको वालेटको कुञ्जीहरू आयात गर्न र पहिलेको DeHub खाता माइग्रेट गर्न छुट्टै विकल्पहरू छन्, त्यसैले नयाँ साइन - अपहरूले तिनीहरू बीच कहिल्यै छनौट गर्नुपर्दैन ।',
    accountsB8: 'छोड्दै:',
    accountsB8Desc: 'तपाईं आफ्नो खाता आफै सेटिंग्सबाट मेटाउन सक्नुहुन्छ । तपाईंको प्रोफाइल, अपलोडहरू र भण्डारण गरिएका मिडियाहरू, जगेडा प्रतिलिपिहरू सहित, मेटाइएको छ, र एप्पल लिंकको साथ साइन इन रद्द गरिएको छ । पहिले नै सार्वजनिक ब्लकचेनमा लेखिएको कुनै पनि कुरा त्यहाँ रहन्छ ।',
    uploadGallery: 'एउटा पोष्टले एउटा भन्दा धेरै तस्बिरहरू बोक्न सक्छ: चारवटा ब्याज बिना, प्रत्येक ब्याज टियरको साथ मेगालोडनमा बीस सम्म बढ्छ, र प्रत्येक छवि 42.069 MB सम्म हुन सक्छ । रचनाकारमा पोष्ट गर्नु अघि तपाईंले चाहेको क्रममा छविहरू तान्नुहोस्, चित्र बनाउनुहोस् वा लेख्नुहोस्, र पूर्ण रिजोलुसन, चुच्चो र जुममा मूल फाइल हेर्नको लागि कुनै पनि फोटो फुलस्क्रिन खोल्नुहोस् ।',
    labelComposerTools: 'कम्पोजर टूलहरू:',
