    profileB3: 'कुल पहुँच:',
    profileB3Desc: 'तपाईंको अन्य सामाजिक लिङ्क गर्नुहोस् र प्रोफाइलले तपाईंको DeHub अनुयायीहरूमा तपाईंको अनुयायीहरूको संख्या थप गर्दछ, ब्रेकडाउन एक ट्याप टाढा छ ।',
