    dpayDesc: 'DeHub Pay: स्ट्राइप मार्फत कार्डको साथ किन्नुहोस्, वा अन्य चेनहरूबाट क्रिप्टोको साथ, $ 0.50 बाट',
    topUpCardDesc: 'खरीद पृष्ठ DeHub Pay मा चल्छ । कार्डबाट भुक्तानी गर्नुहोस्, वा तपाईंले अर्को चेनमा राखेको क्रिप्टोको साथ भुक्तानी गर्नुहोस् र यो तपाईंको लागि रूपान्तरण हुन्छ । न्यूनतम $ 0.50 हो । ETH र USDC पनि कार्ड मार्फत MoonPay मार्फत किन्न सकिन्छ, तपाईं पहिले नै चेनमा हुनुहुन्छ, र एपले तपाईंलाई हस्ताक्षर गरेको वालेटमा सिधै अवतरण गर्न सक्नुहुन्छ । एक पटक खरिद भूमिमा पुगेपछि तपाईंले यसलाई एक ट्यापमा फिडमा साझेदारी गर्न सक्नुहुन्छ ।',
    badgeUnlock4: 'सुपरपावरहरू, प्रोफाइल कस्मेटिक्स, अधिक प्रोफाइल स्लटहरू, प्रति पोष्ट अधिक छविहरू, र तपाईंको आफ्नै इमोजी, स्टिकर र GIF प्याकहरू ।',
    tipDesc3: 'सुझावहरूले पोष्टहरू, टिप्पणीहरू, प्रत्यक्ष सन्देशहरू र प्रत्यक्ष स्ट्रिमहरूमा काम गर्दछ । यदि तपाईंसँग DeHub टोकनहरूको कमी छ भने, टिप शीटले तपाईंको अन्य ब्यालेन्सहरू — USDC, ETH वा बेस, BNB चेन, Robinhood Chain वा ARC मा टोकनहरू प्रदान गर्दछ — र टिप बाहिर जानु अघि तपाईंको लागि तिनीहरूलाई रूपान्तरण गर्दछ । एकचोटि तपाईंले पोष्ट टिप गरेपछि, यसको टिप बटनले स्पार्कलिंग हीरा देखाउँदछ ताकि तपाईंले पहिले नै कहाँ दिनुभएको छ भनेर हेर्न सक्नुहुन्छ ।',
    liveStreamDesc: 'लाइभ पोस्ट कम्पोजरबाट वा ब्राउजरमा वा एन्कोडरबाट लाइभ जानुहोस्। स्ट्रीमहरू DeHubको स्वतन्त्र इन्गेस्टमा प्रकाशित हुन्छन् र वेबआरटीसीको माध्यमबाट नजिकै वास्तविक समयमा चल्छन्, जसमा लाइभपियर स्वचालित रूपमा फ्यालबेकको रूपमा काम गर्दछ जब कुनै नेटवर्क इन्गेस्टसँग जोडिन नसक्छ। प्रत्येक स्ट्रीममा अनुमति रहित र सेंसरशिप प्रतिरोधी हुन्छ, आफ्नै च्याट भएको हुन्छ र त्यसको समाप्ति भएको क्षणमा रिप्लेमा परिणत हुन्छ।',
    keyFeat1: 'अन - चेन मिन्टिंग वैकल्पिकको साथ, कम्पोजरबाट प्रत्यक्ष जानुहोस्',
    keyFeat2: 'तहबद्ध उपहार एनिमेशनहरू र टिप मेसेजहरू स्ट्रीममा उच्चारण गरिन्छ।',
