    spDescTeamUp: 'सात अन्य खाताहरूसँग वालेट पावर मिलाउनुहोस् । टोलीमा सबैले पूल गरिएको ब्यालेन्स अनलक भएको ब्याज लगाउँछन्, र यसको कुनै मूल्य छैन । एक टोली निजी हुन सक्छ, त्यसैले मानिसहरूले सामेल हुन अनुरोध गर्छन् र मालिकले तिनीहरूलाई अनुमोदन गर्दछ ।',
    feedsHomeDesc: 'पाठ, छवि, लेख, भिडियो, अडियो र प्रत्यक्ष पोष्टहरूको मिश्रित फिड । मनपर्नेहरू, टिप्पणीहरू, रिपोस्टहरू, उद्धरणहरू, बुकमार्कहरू र टोकन टिपिंगहरू प्रत्येक कार्डमा निर्माण गरिएका छन्, र पोष्टहरू गेट गर्न, भुक्तानी - प्रति - दृश्य बनाउन वा वाच2earn मा सेट गर्न सकिन्छ । ताकि कसैले यसलाई बाढी गर्न नपरोस्, घरको फिडले प्रति दिन प्रत्येक लेखकको पोष्टहरूको सीमित संख्या बोक्छ: एउटा ब्याज बिना र प्रत्येक ब्याज टियरको लागि एक थप, मेगालोडनमा चौध सम्म । सबै कुरा अझै पनि लेखकको प्रोफाइलमा र निम्न क्रमबद्धमा देखा पर्दछ ।',
    feedsSort: 'फिल्टरिङ र सङ्कलन:',
