    feedsReactionsDesc: 'दस प्रतिक्रियाहरू लाइक बटनको पछाडि बस्छन्: जस्तै, प्रेम, सम्मान, तातो, १००, lol, sad, cry, poo र dislike । मन नपराउने बाहेक प्रत्येकले कुल जस्तै पोष्टमा गणना गर्दछ । यसलाई मनपराउनको लागि पोष्टलाई डबल - ट्याप गर्नुहोस्, यसलाई मनपराउनको लागि ट्रिपल - ट्याप गर्नुहोस्, र ट्रे खोल्नको लागि बटन होल्ड गर्नुहोस्, जसले कसले प्रतिक्रिया दियो र केको साथ देखाउँछ । कार्डमा प्रमुख आइकन भनेको पोस्टले जुनसुकै प्रतिक्रियालाई सबैभन्दा बढी आकर्षित गर्छ । प्रतिक्रिया रिएक्टरको ब्याजले भारित हुन्छ, त्यसैले कसले प्रतिक्रिया दियो र कतिले गरे । सेटिंग्समा बायाँ - हाते मोडले बारको बायाँतिर लाइक बटन सार्छ ।',
    feedsCommentsDesc: 'प्रत्येक पोष्टले आफ्नै मनपर्ने, मन नपर्ने र दृश्य गणनाको साथ टिप्पणीहरू बोक्छ । यसलाई जवाफ दिन टिप्पणी ट्याप गर्नुहोस् । जब एक लेखक आफैंलाई जवाफ दिन्छन् तब रन एक क्रमांकित धागो बन्छ । एक सर्जकले आफ्नै पोष्टमा एउटा टिप्पणी पिन गर्न सक्दछ; त्यसपछि थ्रेडले त्यो पिनको साथ नेतृत्व गर्दछ, त्यसपछि एक सशुल्क टिप्पणी एङ्कर, त्यसपछि पाँच सबैभन्दा धेरै टिप गरिएका टिप्पणीहरू । सिर्जनाकर्ताहरूले पोष्टको लागि साझा ग्राउन्ड मोड खोल्न सक्छन्, जसले पाठकहरूलाई उनीहरूको पहिलो जवाफ दिनु अघि अर्को पक्षको सब भन्दा बलियो बिन्दुको लागि सोध्छ, र टिप्पणी बक्समा AI बटनले तपाईंको टोन जाँच गर्दछ, यसको शैली परिवर्तन गर्दछ वा हिज्जे र व्याकरण फिक्स गर्दछ । कुनै पनि टिप्पणी यसको सेयर मेनुबाट रिपोर्ट गर्न सकिन्छ ।',
    feedsMuteDesc: 'कुनै पनि पोष्टमा मेनुबाट लेखकलाई म्यूट वा ब्लक गर्नुहोस् । म्युटिङले तिनीहरूलाई तपाईंको फिडबाट चुपचाप बाहिर निकाल्छ र पूर्ववत गर्न सकिन्छ; अवरोध अगाडि बढ्छ, दुबै तरिकाले काम गर्दछ र सन्देश पनि काट्छ ।',
