    accountsTitle: 'खाता र साइन इन',
    accountsDesc2: 'एक व्यक्तिले एउटै ब्राउजरबाट धेरै पहिचानहरू चलाउन सक्छ । प्रोफाइलहरू सेटिङ → प्रोफाइलमा व्यवस्थापन गरिन्छ: खाता थप्नुहोस्, तिनीहरू बीच स्विच गर्नुहोस्, र DeHub ले सम्पूर्ण सत्र — वालेट, फिड, सन्देशहरू र सूचनाहरू — एक चरणमा स्वाप गर्दछ । प्रोफाइल थप्दा तपाईं कहिले पनि साइन आउट गर्नुहुन्न जुन तपाईंमा हुनुहुन्छ, र पूरा गर्न नसकिने स्विच तपाईं जहाँ हुनुहुन्थ्यो त्यहाँ फिर्ता रोल हुन्छ । तपाईंले आफ्नो स्टेकिङ ब्याजको साथ सूची स्केलमा कतिवटा प्रोफाइलहरू पार्क गर्न सक्नुहुन्छ ।',
    accountsB1: 'सामाजिक साइन - इन:',
