    accountsB5: 'नयाँ सदस्यहरू:',
    tocAllowance: 'पोस्टिङ भत्ता',
    allowanceTitle: 'दैनिक पोस्टिङ भत्ता',
    allowanceIntro: 'DeHub मा पोष्टिंग हरेक दिन निःशुल्क हुन्छ, एक भत्ता सम्म जुन तपाईंको स्टेकिङ ब्याजको साथ मापन गर्दछ । सबैले दिनको दशवटा पाठ पोष्टहरू र एक गीगाबाइट भिडियो, छविहरू र अडियोबाट सुरु गर्छन् । या त एक पछि जानुहोस् र बाँकी दिनको लागि DeHub टोकनमा भुक्तानी गरिन्छ — 10c एक पाठ पोष्ट, $ 2 एक गीगाबाइट, केवल भागमा चार्ज गरिएको छ ।',
    allowanceIntro2: 'पाठ पोष्टहरू र मिडियाहरू छुट्टै पोखरीहरू हुन् । एउटाबाट बाहिर निस्कँदा अर्कोलाई छुँदैन, त्यसैले भिडियो अपलोड गर्दा बिताएको एक दिनले अझै पनि सबै दशवटा पाठ पोष्टहरू निःशुल्क छोड्छ । दुबै मध्यरात UTC मा रिसेट हुन्छन् ।',
