    feedsTitle: 'फिड र सामग्री ढाँचाहरू',
    feedsDesc: 'DeHub घरको सतह एक एकल ट्याब गरिएको फिड हो जसले प्रत्येक सामग्री ढाँचा एकैचोटि बोक्छ । सिर्जनाकर्ताहरूलाई एक माध्यममा जबरजस्ती गर्नुको सट्टा, फिडले पाठ, छविहरू, लामो - फारम भिडियो, छोटो - फारम रिलहरू, संगीत र प्रत्यक्ष स्ट्रिमहरू एक स्क्रोलमा मिसाउँछ, र दर्शकहरूलाई उनीहरूले चाहेको समयमा एकल ढाँचामा साँघुरो बनाउन दिन्छ । ढाँचाको पर्वाह नगरी प्रत्येक कार्डले समान सामाजिक र मुद्रीकरण नियन्त्रणहरू बोक्छ: जस्तै, टिप्पणी, पुनःपोस्ट, उद्धरण, बुकमार्क र DeHub टोकनमा टिप ।',
    feedsDesc2: 'फिडको माथिल्लो भागमा ट्याबको रूपमा ढाँचाहरू देखा पर्छन् । पूर्वनिर्धारित गृह ट्याबले तपाईंले पछ्याउनुहुने मानिसहरू र समुदायहरूबाट सबै कुरा इन्टरलिफ्ट गर्दछ; समर्पित ट्याबहरूले एक माध्यमलाई अलग गर्दछ ताकि तपाईं, उदाहरणका लागि, लामो - फारम भिडियो वा संगीत मात्र ब्राउज गर्न सक्नुहुनेछ । र्याङ्किङ्ग यस पृष्ठको तल थप कागजात गरिएको प्लेटफर्म लिडरबोर्ड एल्गोरिथ्मद्वारा संचालित हुन्छ, त्यसैले गुणस्तर र संलग्नता, विज्ञापन खर्च होइन, पहुँच निर्णय गर्नुहोस् ।',
