    doCollectItem1: 'तपाईँले साइन-इन गरेको पहिचान — यदि तपाईँले यस्तो मार्ग चयन गरेको छ भने एक ईमेल पते वा फोन नम्बर, सोशल साइन-इनको लागि Google, Apple वा Telegramले रिटर्न गरेको पहिचान, वा एक पासकीको पब्लिक क्रेडेनसियल। एक वॉलेट साइन-इनले मात्र तपाईँको पब्लिक एड्रेस दिन्छ।',
