    doCollectItem8: 'कुन पेजहरू भेटिएका छन् र मानिसहरूले कसरी एकबाट अर्कोमा हुन्छन्, ताकि हामीले हेर्न सकौं के काम गर्दछ। तपाईँको आफ्नै भेटिएका सहयोगी पेजहरूको आफ्नो भेटिएको डेटा गणना गरिएको छैन।',
    dontCollectItem6: 'तपाईँको कार्डको विवरण, र तपाईँको एन्ड-टु-एन्ड एन्क्रिप्टेड डिरेक्ट मेसेजहरूको पाठ कुनै पनि रूपमा पठाइएको छैन — यी हामीलाई पढ्न सकिँदैन। मेसेजमा फोटो, भिडियो र फाइलहरू, र एन्क्रिप्सन अनलक गरेको छैन भनेको व्यक्तिको मेसेजहरू, अझै एन्ड-टु-एन्ड एन्क्रिप्टेड छैनन्।',
    thirdPartyItem6: 'DeHubको स्वयम् इन्जेस्ट लाइभ भिडियो ल्याउँछ, र लाइभ ऑडियो रुमहरू Agora ले ल्याउँछ',
    thirdPartyItem8: 'तपाईँले एक जनसङ्ख्यामा पठाउने पाठ र मीडिया — अनुवाद, उपशीर्षक वा डबिङ्ग फिचर — यसको लागि मात्र एक प्रोवाइडरको लागि पठाइएको छ, यसको मात्र एक अनुरोधको लागि। निजी पाठ — मेसेज, प्रतिक्रियाहरू र असिस्टेन्ट च्याटहरू — कुनै पनि प्रोवाइडरको फ्री टियरमा प्रशिक्षणको लागि प्राप्त भएको कुरामा कुनै पनि रूपमा पठाइएको छैन।',
    thirdPartyItem9Prefix: 'क्रिप्टोमा खरिद र भुक्तानी:',
