    thirdPartyItem10Prefix: 'मल्टि-पोस्टिङ्:',
    thirdPartyItem10: 'जब तपाईं अन्य सामाजिक खाताहरू जडान गर्नुहुन्छ, तपाईंले पठाउन रोज्नु भएको पोस्टहरू पोस्टिङ सेवा मार्फत ती प्लेटफर्महरूमा र तपाईंले अनुमोदन गर्नुभएको हस्ताक्षरकर्ता मार्फत फारकास्टरमा डेलिभर गरिन्छ ।',
    dataSovereigntyItem5: 'AI प्रणालीहरूले तपाईंको काममा तालिम लिन सक्छन् कि भनेर तपाईंले छनौट गर्नुहुन्छ । तपाईंले यसलाई सेटिंग्समा स्विच अफ नगरेसम्म यसलाई अनुमति छ, र तपाईंको छनौट हामीले नियन्त्रण गर्ने पृष्ठहरूमा क्रलरहरूलाई प्रकाशित गरिएको छ',
