    q20: 'के DeHub टोकनहरू लगानी हुन्?',
    a20: 'होइन, DeHub टोकनहरू DeHub इकोसिस्टम भित्र उपयोगिता उद्देश्यका लागि कडाईका साथ छन्, जस्तै इन - गेम वा इन - एप डिजिटल मुद्राहरू । तिनीहरू लगानीका साधनहरू होइनन् र बजारहरू अत्यधिक अस्थिर छन् ।',
    q21: 'सामग्री मोडेरेसन कसरी काम गर्छ?',
