    step1Desc: 'Dehub.io खोल्नुहोस् र साइन इन गर्नुहोस् ट्याप गर्नुहोस् । गुगल, एप्पल, टेलिग्राम, ईमेल, एसएमएस, पासकी वा वालेट रोज्नुहोस् । पृष्ठभूमिमा तपाईंको लागि एक गैर - कस्टोडियल वालेट सिर्जना गरिएको छ — तपाईंसँग कुञ्जीहरू छन् — र ग्यास प्रायोजित छ, त्यसैले तपाईंले सुरु गर्नु अघि कोष गर्न केही छैन ।',
    step2Title: 'आफ्नो प्रोफाइल सेट अप गर्नुहोस्',
    step2Desc: 'सेटिंग्स → प्रोफाइलमा एक प्रदर्शन नाम, प्रयोगकर्ता नाम, अवतार, कभर छवि र बायो थप्नुहोस्, र तपाईंको अन्य सामाजिक लिङ्क गर्नुहोस् ताकि तपाईंको प्रोफाइलले तपाईंको कुल पहुँच देखाउँछ । तपाईं त्यहाँ हुँदा → सेटिंग्स उपस्थितिमा एउटा विषयवस्तु छान्नुहोस्, र यदि तपाईं वरिपरि देखाउन चाहनुहुन्छ भने वैकल्पिक निर्देशित पैदल यात्रा गर्नुहोस् ।',
    step3Title: 'आफ्नो पहिलो पोस्ट बनाउनुहोस्',
    step3Desc: 'सिर्जना गर्नुहोस् ट्याप गर्नुहोस् । पोष्ट लेख्नुहोस्, छविहरू, भिडियो वा अडियो थप्नुहोस्, लामो - फारम लेखनको लागि लेखमा स्विच गर्नुहोस्, वा प्रत्यक्ष जानुहोस् । पोस्टिङ दैनिक भत्तासम्म निःशुल्क छ — दसवटा पाठ पोष्टहरू र एक गीगाबाइट मिडिया एक दिनमा ब्याज बिना । पोष्ट अन - चेन टकसाल गर्नु वैकल्पिक छ र पछि गर्न सकिन्छ ।',
    step4Title: 'आफ्नो श्रोताबाट कमाउनुहोस्',
    step4Desc: 'हरेक पोस्टलाई DeHub टोकनमा टिप गर्न सकिन्छ । त्यहाँबाट तपाईं सदस्यताहरू बेच्न सक्नुहुन्छ, भुक्तानी - प्रति - दृश्य पोष्टहरू प्रकाशित गर्न सक्नुहुन्छ, प्रत्यक्ष सन्देशहरूको लागि न्यूनतम टिप सेट गर्न सक्नुहुन्छ, स्टोर खोल्न सक्नुहुन्छ, इनामहरू पोस्ट गर्न सक्नुहुन्छ र तपाईंले ल्याउने व्यक्तिहरूबाट कमाउनको लागि आफ्नो सम्बद्ध लिंक साझेदारी गर्न सक्नुहुन्छ ।',
    step5Title: 'ब्याजको लागि टोकनहरू होल्ड गर्नुहोस्',
    step5Desc: 'DeHub टोकनहरू होल्ड वा स्टेक गर्नाले क्र्याबदेखि मेगालोडनसम्म ब्याज कमाउँछ । ब्याजले तपाईंको शुल्क घटाउँछ, तपाईंको पोष्टिंग भत्ता बढाउँछ, सुपरपावरहरू अनलक गर्दछ र तपाईंको विचार, प्रतिक्रियाहरू र भोटहरूमा तौल थप गर्दछ ।',
